// Matches only http:// and https:// URLs. Misspelled or other schemes
// (ftp://, mailto:, file://, javascript:, data:, htp://, bare domains, ...)
// intentionally do not match.
const URL_REGEX = /https?:\/\/[^\s]+/g;

const ANCHOR_CLASS_NAME =
  "break-all text-blue-600 underline hover:text-blue-800";

/**
 * Removes punctuation that commonly sits adjacent to a URL in prose so it is
 * not treated as part of the link. Trailing sentence punctuation is always
 * stripped; closing brackets are only stripped when they are unbalanced (so
 * URLs that legitimately contain balanced brackets are preserved).
 */
const trimTrailingPunctuation = (url: string): string => {
  let result = url;

  while (result.length > 0) {
    const last = result[result.length - 1];

    if (".,;:!?".includes(last)) {
      result = result.slice(0, -1);
      continue;
    }

    const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
    if (last in pairs) {
      const open = pairs[last];
      const openCount = result.split(open).length - 1;
      const closeCount = result.split(last).length - 1;
      if (closeCount > openCount) {
        result = result.slice(0, -1);
        continue;
      }
    }

    break;
  }

  return result;
};

const linkifyString = (text: string): React.ReactNode[] => {
  const nodes: React.ReactNode[] = [];
  let lastIndex = 0;
  let key = 0;
  let match: RegExpExecArray | null;

  URL_REGEX.lastIndex = 0;
  while ((match = URL_REGEX.exec(text)) !== null) {
    const raw = match[0];
    const start = match.index;
    const url = trimTrailingPunctuation(raw);

    if (start > lastIndex) {
      nodes.push(text.slice(lastIndex, start));
    }

    nodes.push(
      <a
        key={`link-${key++}`}
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className={ANCHOR_CLASS_NAME}
        onClick={(event) => event.stopPropagation()}
      >
        {url}
      </a>,
    );

    // Punctuation that was excluded from the URL is rendered as plain text.
    const trailing = raw.slice(url.length);
    if (trailing) {
      nodes.push(trailing);
    }

    lastIndex = start + raw.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
};

const LinkifyText = ({
  children,
}: {
  children?: React.ReactNode;
}): JSX.Element => {
  if (children === null || children === undefined) {
    return <></>;
  }

  if (typeof children === "number") {
    return <>{String(children)}</>;
  }

  if (typeof children === "string") {
    if (!children.includes("http")) {
      return <>{children}</>;
    }

    return <>{linkifyString(children)}</>;
  }

  return <>{children}</>;
};

export default LinkifyText;
